insert into lessons (id, unit_id, order_index, title, description, type, xp_reward) values
 ('935cb024-770a-59b7-b0ba-35ed349abeb7','b33fd38d-60a8-58c7-bd4c-233a60956b23',1,$p$Contar con «că»: los tiempos$p$,$p$Contar con «că»: los tiempos$p$,'lesson',15),
 ('af578b71-1197-5045-b586-a61902c96c86','b33fd38d-60a8-58c7-bd4c-233a60956b23',2,$p$«Să», no «că»: la orden reportada$p$,$p$«Să», no «că»: la orden reportada$p$,'lesson',15),
 ('0ad3ae4e-145c-5ba7-b3b5-5df758add112','b33fd38d-60a8-58c7-bd4c-233a60956b23',3,$p$Preguntas indirectas: dacă$p$,$p$Preguntas indirectas: dacă$p$,'lesson',15),
 ('c70f59ec-6ac8-5fc6-8151-7098d2b35921','b33fd38d-60a8-58c7-bd4c-233a60956b23',4,$p$Aquí→allí: los deícticos$p$,$p$Aquí→allí: los deícticos$p$,'lesson',15),
 ('f0ce36c5-3127-576d-b420-6fcc5c169d29','b33fd38d-60a8-58c7-bd4c-233a60956b23',5,$p$🏁 Checkpoint Unitatea 20$p$,$p$Repasa la vorbirea indirecta: el paso del estilo directo al indirecto con «că», el desplazamiento de tiempos (present→imperfect, perfect compus→mai mult ca perfectul), el imperativo reportado que se vuelve «să» + conjunctiv (mi-a spus SĂ plec, no «că»), las preguntas indirectas de sí/no con «dacă» y con interrogativo (unde/când/ce), y los deícticos que se desplazan (aici→acolo, azi→în acea zi, mâine→a doua zi).$p$,'checkpoint',40)
