 ('4494cf50-f7d2-53f9-a9e5-46cc9f90cae8','20000000-0000-0000-0000-000000000007','B2',23,$p$Se dice, hace falta: lo impersonal$p$,'#7F8C8D','campaign')
insert into lessons (id, unit_id, order_index, title, description, type, xp_reward) values
 ('5cff87cf-647b-53ce-896e-89e7414fa437','4494cf50-f7d2-53f9-a9e5-46cc9f90cae8',1,$p$Se pare, se spune, se știe: lo que se dice$p$,$p$Se pare, se spune, se știe: lo que se dice$p$,'lesson',15),
 ('64042d7a-5535-54d5-a95e-3fff2707217f','4494cf50-f7d2-53f9-a9e5-46cc9f90cae8',2,$p$E nevoie, merită, e cazul să…$p$,$p$E nevoie, merită, e cazul să…$p$,'lesson',15),
 ('268cb8ba-fca5-5a5d-8743-4c59308ec00e','4494cf50-f7d2-53f9-a9e5-46cc9f90cae8',3,$p$Aici se muncește: el impersonal con «se»$p$,$p$Aici se muncește: el impersonal con «se»$p$,'lesson',15),
 ('46c5baf0-4f4b-542b-a903-666dd9ff9bcc','4494cf50-f7d2-53f9-a9e5-46cc9f90cae8',4,$p$E greu să… y no soporto (a suporta)$p$,$p$E greu să… y no soporto (a suporta)$p$,'lesson',15),
 ('83383ff7-2f4f-510d-ad37-ee7b95ad0aa7','4494cf50-f7d2-53f9-a9e5-46cc9f90cae8',5,$p$🏁 Checkpoint Unitatea 23$p$,$p$Repasa las construcciones impersonales del rumano: «se pare că / se spune că / se știe că», «mi se pare că» con el dativo, «e nevoie să / merită să / e cazul să / se cuvine să» + conjunctiv, el reflexivo impersonal «aici se muncește», «nu se știe niciodată», «îmi vine să» y «e greu / ușor / imposibil să», y «a suporta» = soportar/tolerar (¡ojo! «apoyar» es a sprijini / a susține).$p$,'checkpoint',40)
