('82ef9805-3c10-56ae-8857-e509b4cb6182'::uuid,'20000000-0000-0000-0000-000000000007'::uuid,'B2','reading','match',$p$Empareja cada frase impersonal con su traducción. En rumano el «se» + 3ª persona hace lo impersonal.$p$,$j${"pairs": [{"en": "Aici se muncește mult.", "es": "Aquí se trabaja mucho."}, {"en": "Nu se știe niciodată.", "es": "Nunca se sabe."}, {"en": "În România se vorbește românește.", "es": "En Rumanía se habla rumano."}]}$j$::jsonb,$j${"pairs": [["Aici se muncește mult.", "Aquí se trabaja mucho."], ["Nu se știe niciodată.", "Nunca se sabe."], ["În România se vorbește românește.", "En Rumanía se habla rumano."]]}$j$::jsonb,0.68,ARRAY[$p$unidad23$p$, $p$reflexiv_impersonal$p$, $p$reading$p$]),
